#include "AssetManifestSnapshot.h"

#include <algorithm>
#include <cctype>

namespace NeoEngine {
namespace {
constexpr uint32_t kMagic=0x31464D41U;
bool ValidId(std::string_view id){return !id.empty()&&id.size()<=96U&&std::all_of(id.begin(),id.end(),[](unsigned char c){return std::isalnum(c)||c=='-'||c=='_'||c=='.';});}
uint64_t Hash(const std::vector<uint8_t>& bytes){uint64_t hash=1469598103934665603ULL;for(uint8_t byte:bytes){hash^=byte;hash*=1099511628211ULL;}return hash;}
void U32(std::vector<uint8_t>& out,uint32_t value){for(uint8_t shift=0;shift<4U;++shift)out.push_back(static_cast<uint8_t>(value>>(shift*8U)));}
void U64(std::vector<uint8_t>& out,uint64_t value){for(uint8_t shift=0;shift<8U;++shift)out.push_back(static_cast<uint8_t>(value>>(shift*8U)));}
bool ReadU32(const std::vector<uint8_t>& in,size_t& offset,uint32_t& value){if(offset+4U>in.size())return false;value=0;for(uint8_t shift=0;shift<4U;++shift)value|=static_cast<uint32_t>(in[offset+shift])<<(shift*8U);offset+=4U;return true;}
bool ReadU64(const std::vector<uint8_t>& in,size_t& offset,uint64_t& value){if(offset+8U>in.size())return false;value=0;for(uint8_t shift=0;shift<8U;++shift)value|=static_cast<uint64_t>(in[offset+shift])<<(shift*8U);offset+=8U;return true;}
bool ReadText(const std::vector<uint8_t>& in,size_t& offset,size_t length,std::string& value){if(length>in.size()-offset)return false;value.assign(reinterpret_cast<const char*>(in.data()+offset),length);offset+=length;return true;}
bool Same(const AssetDefinition& left,const AssetDefinition& right){return left.id==right.id&&left.kind==right.kind&&left.dependencies==right.dependencies&&left.state==right.state&&left.contentHash==right.contentHash&&left.byteSize==right.byteSize;}
}
bool AssetManifestSnapshot::Capture(const AssetRegistry& registry){entries_=registry.All();if(entries_.size()>AssetRegistry::kMaxAssets){lastError_=AssetManifestError::Capacity;return false;}std::sort(entries_.begin(),entries_.end(),[](const AssetDefinition& left,const AssetDefinition& right){return left.id<right.id;});lastError_=AssetManifestError::None;return true;}
bool AssetManifestSnapshot::Serialize(std::vector<uint8_t>& out) const {if(entries_.size()>AssetRegistry::kMaxAssets){return false;}out.clear();U32(out,kMagic);out.push_back(kVersion);U32(out,static_cast<uint32_t>(entries_.size()));for(const AssetDefinition& entry:entries_){if(!ValidId(entry.id)||entry.dependencies.size()>AssetRegistry::kMaxDependencies){return false;}out.push_back(static_cast<uint8_t>(entry.id.size()));out.insert(out.end(),entry.id.begin(),entry.id.end());out.push_back(static_cast<uint8_t>(entry.kind));out.push_back(static_cast<uint8_t>(entry.state));U64(out,entry.contentHash);U32(out,entry.byteSize);out.push_back(static_cast<uint8_t>(entry.dependencies.size()));for(const std::string& dependency:entry.dependencies){if(!ValidId(dependency)){return false;}out.push_back(static_cast<uint8_t>(dependency.size()));out.insert(out.end(),dependency.begin(),dependency.end());}}U64(out,Hash(out));return true;}
bool AssetManifestSnapshot::Deserialize(const std::vector<uint8_t>& bytes){if(bytes.size()<17U){lastError_=AssetManifestError::Corrupt;return false;}size_t offset=0;uint32_t magic=0;if(!ReadU32(bytes,offset,magic)||magic!=kMagic){lastError_=AssetManifestError::Corrupt;return false;}if(offset>=bytes.size()||bytes[offset++]!=kVersion){lastError_=AssetManifestError::UnsupportedVersion;return false;}uint32_t count=0;if(!ReadU32(bytes,offset,count)||count>AssetRegistry::kMaxAssets){lastError_=AssetManifestError::Capacity;return false;}std::vector<AssetDefinition> parsed;parsed.reserve(count);for(uint32_t index=0;index<count;++index){if(offset>=bytes.size()){lastError_=AssetManifestError::Corrupt;return false;}const uint8_t idLength=bytes[offset++];AssetDefinition entry{};if(idLength==0U||idLength>96U||!ReadText(bytes,offset,idLength,entry.id)||!ValidId(entry.id)||std::any_of(parsed.begin(),parsed.end(),[&entry](const AssetDefinition& prior){return prior.id==entry.id;})){lastError_=AssetManifestError::DuplicateId;return false;}if(offset+2U>bytes.size()){lastError_=AssetManifestError::Corrupt;return false;}const uint8_t kind=bytes[offset++],state=bytes[offset++];if(kind>static_cast<uint8_t>(AssetKind::Audio)||state>static_cast<uint8_t>(AssetState::Ready)){lastError_=AssetManifestError::InvalidEntry;return false;}entry.kind=static_cast<AssetKind>(kind);entry.state=static_cast<AssetState>(state);if(!ReadU64(bytes,offset,entry.contentHash)||!ReadU32(bytes,offset,entry.byteSize)||offset>=bytes.size()){lastError_=AssetManifestError::Corrupt;return false;}const uint8_t dependencyCount=bytes[offset++];if(dependencyCount>AssetRegistry::kMaxDependencies){lastError_=AssetManifestError::Capacity;return false;}for(uint8_t dependencyIndex=0;dependencyIndex<dependencyCount;++dependencyIndex){if(offset>=bytes.size()){lastError_=AssetManifestError::Corrupt;return false;}const uint8_t dependencyLength=bytes[offset++];std::string dependency;if(dependencyLength==0U||dependencyLength>96U||!ReadText(bytes,offset,dependencyLength,dependency)||!ValidId(dependency)||dependency==entry.id||std::find(entry.dependencies.begin(),entry.dependencies.end(),dependency)!=entry.dependencies.end()){lastError_=AssetManifestError::InvalidEntry;return false;}entry.dependencies.push_back(std::move(dependency));}parsed.push_back(std::move(entry));}uint64_t expected=0;if(!ReadU64(bytes,offset,expected)){lastError_=AssetManifestError::Corrupt;return false;}if(offset!=bytes.size()){lastError_=AssetManifestError::TrailingBytes;return false;}if(Hash(std::vector<uint8_t>(bytes.begin(),bytes.end()-8U))!=expected){lastError_=AssetManifestError::ChecksumMismatch;return false;}for(const AssetDefinition& entry:parsed)for(const std::string& dependency:entry.dependencies)if(std::none_of(parsed.begin(),parsed.end(),[&dependency](const AssetDefinition& candidate){return candidate.id==dependency;})){lastError_=AssetManifestError::MissingDependency;return false;}entries_=std::move(parsed);lastError_=AssetManifestError::None;return true;}
bool AssetManifestSnapshot::MatchesRegistry(const AssetRegistry& registry){std::vector<AssetDefinition> active=registry.All();std::sort(active.begin(),active.end(),[](const AssetDefinition& left,const AssetDefinition& right){return left.id<right.id;});if(active.size()!=entries_.size()||!std::equal(active.begin(),active.end(),entries_.begin(),Same)){lastError_=AssetManifestError::RegistryMismatch;return false;}lastError_=AssetManifestError::None;return true;}
} // namespace NeoEngine
